-- The six actors already on impromotion.lv, so the site can read from the database from day one.
-- Each actor claims their profile later through an invite (invites.actor_id) and can then edit it,
-- including turning off show_on_site.

insert into public.actors (slug, full_name, stage_name, short_bio, bio, photo_path, skills, formats, languages, regions, socials, show_on_site, status, sort_order)
values
  ('kristers-odzins', 'Kristers Odziņš', 'Mācītājs', 'Pozitīvs. Harizmātisks. Piešķir pasākumam vieglumu un personību.', 'Pozitīvs. Harizmātisks. Daži pat teiktu, ka izskatīgs. Padodas dot vieglumu un personību pasākumam. Izmantojot desmitgades pieredzi improvizācijā, varu pielāgoties visām situācijām, kas pasākuma laikā izvērtīsies.

Ir pieredze kāzu, korporatīvo, dzimšanas dienas balīšu un izrāžu vadīšanā, kā arī pasākumu iesildīšanā. Izmantoju improvizāciju un atrakcijas, lai izkustinātu publiku un veidotu neaizmirstamas atmiņas.', '/assets/img/actor-kristers.webp', array['Pasākumu vadīšana', 'Improvizācijas izrādes', 'Animatora darbs']::text[], array['Kāzas', 'Privāti pasākumi', 'Izrādes', 'Bērnu ballītes', 'Bēres']::text[], array['latviešu']::text[], array['Rīga', 'Visa Latvija']::text[], '{"facebook": "https://www.facebook.com/Kristers.Kukie", "instagram": "https://www.instagram.com/kristersodzins/"}'::jsonb, true, 'approved', 10),
  ('leina-markevica', 'Leina Markevica', 'Zigrīda', 'Dzirkstoša enerģija, kas aizrauj publiku ar aktivitātēm, dejām un tostiem.', 'Meitene ar dzirkstošu enerģiju, kas aizraus publiku. Padodas izklaidēt, iesaistīt un sasmīdināt publiku ar aktivitātēm, dejām un tostiem. Plašā improvizācijas un komēdijas pieredze palīdz pārvērst katru pasākumu neaizmirstamā pieredzē.

Esmu vadījusi izrādes, kāzas un privātus pasākumus, protu būt gan izklaidējoši smieklīga, gan nopietni saviļņojoša. Parunāsim, iepazīsimies un vienosimies par tavu perfekto pasākuma scenāriju.', '/assets/img/actor-leina.webp', array['Pasākumu vadīšana', 'Improvizācijas izrādes', 'Dejas', 'Tosti']::text[], array['Kāzas', 'Privāti pasākumi', 'Izrādes']::text[], array['latviešu']::text[], array['Rīga', 'Visa Latvija']::text[], '{"facebook": "https://www.facebook.com/markevica", "instagram": "https://www.instagram.com/leinamarkevica/", "tiktok": "https://www.tiktok.com/@leinamarkevica"}'::jsonb, true, 'approved', 20),
  ('sandis-elsts', 'Sandis Elsts', 'Sandis Valters', '15+ gadi improvizācijā. Ļoti labi māk izlikties dumjāks, nekā ir.', 'Improvizators ar vairāk nekā 15 gadu pieredzi. Ar improvizāciju sāka nodarboties, jo netīšām aizgāja uz mēģinājumu, domādams, ka tas ir teātra pulciņš. Ļoti labi māk izlikties dumjāks, nekā patiesībā ir, vai vai arī vismaz tā domā.

Ir vadījis gan kolektīvu pasākumus, gan kāzas, gan improvizācijas teātra grupas. Darbojas kā aktieris dažādos improvizācijas kolektīvos, tostarp “Shitty Dinner”, “Plit” un “Spiediens”.', '/assets/img/actor-sandis.webp', array['Pasākumu vadīšana', 'Improvizācijas izrādes']::text[], array['Kāzas', 'Privāti pasākumi', 'Izrādes']::text[], array['latviešu']::text[], array['Rīga', 'Visa Latvija']::text[], '{"facebook": "https://www.facebook.com/sandis.elsts", "instagram": "https://www.instagram.com/sandiselsts/"}'::jsonb, true, 'approved', 30),
  ('robins-reins', 'Robins Reins', 'Rozā', 'Pamēģinājis visu: rakt, lidot, dejot, kompjūterot. Gan jau atradīs vietu arī jūsu pasākumā.', 'Nosvērts. Mierīgs. Dažreiz nemierīgs. Uztaisām jauku un pozitīvu pasākumu kopā! Improvizācijas teātrī darbojos gandrīz desmit gadus, esmu improvizējis gan Latvijā, gan citā vietā Latvijā!

Pamēģinājis esmu visu, ko var: studēt, rakt, lidot, dejot, dziedāt, būvēt, kompjūterot, prezentēt, pārdot, analizēt, krāsot un mehāniķot. Tāpēc gan jau atradīsim, kā šo pieredzi integrēt tavā pasākumā!', '/assets/img/actor-robins.webp', array['Pasākumu vadīšana', 'Improvizācijas izrādes', 'Sporta spēles', 'Viktorīnas']::text[], array['Korporatīvie pasākumi', 'Privāti pasākumi', 'Izrādes']::text[], array['latviešu']::text[], array['Rīga', 'Visa Latvija']::text[], '{"facebook": "https://www.facebook.com/RobinsRein", "instagram": "https://www.instagram.com/robinrein/"}'::jsonb, true, 'approved', 40),
  ('rihards-zeila', 'Rihards Zeiļa', 'Burkāns', 'Improvizācijas apmācības un tiešsaistes kursi. Mācījies arī Koh Phangan salā.', 'Rihards ir darbojies improvizācijas kolektīvos “Džins” un “Plit”, kā arī piedalījies “Spiediens” meistarklasēs. Apguvis improvizācijas mākslu arī Taizemes salā Koh Phangan pie pieredzējuša Kalifornijas improvizācijas pasniedzēja Breeze.', '/assets/img/actor-rihards.webp', array['Komandas treniņi', 'Apmācības']::text[], array['Apmācības', 'Tiešsaistes pasākumi']::text[], array['latviešu']::text[], array['Rīga', 'Visa Latvija']::text[], '{"facebook": "https://www.facebook.com/profile.php?id=100000487541249", "x": "https://twitter.com/rihards_ze", "instagram": "https://www.instagram.com/rihards.ze/", "tiktok": "https://www.tiktok.com/search?q=rihards.ze"}'::jsonb, true, 'approved', 50),
  ('iluta-reinberga', 'Iluta Reinberga', 'Luta', 'Radoša dāma ar dzirkstelīti, kas jūsu vīziju pārvērš realitātē.', 'Esmu radoša dāma ar savu dzirkstelīti, kas spēs tavu vīziju radīt realitātē. Improvizācija ir daļa no manas dzīves; tās pamatlicēji ir slavenie “Spiediens” improvizatori!

Man ir gadiem gūta pieredze pasākumu organizēšanā, vadīšanā un promociju projektu vadībā ar plaši atpazīstamiem zīmoliem Latvijā. Es ticu, ka visi ir pelnījuši kārtīgi izsmieties, jo prieks vairo prieku!', '/assets/img/actor-iluta.webp', array['Pasākumu vadīšana', 'Pasākumu organizēšana']::text[], array['Korporatīvie pasākumi', 'Privāti pasākumi']::text[], array['latviešu']::text[], array['Rīga', 'Visa Latvija']::text[], '{"facebook": "https://www.facebook.com/iluta.reinberga.9", "instagram": "https://www.instagram.com/lutas_skaistumnica/"}'::jsonb, true, 'approved', 60);

update public.actors set troupe_id = (select id from public.troupes where slug = 'impromotion');

update public.actors set quip = 'Daži pat teiktu: izskatīgs.' where slug = 'kristers-odzins';
